INSERT INTO questions (question, answer, knowledge_point, question_type, question_category, content_category, core_connotation, created_at) VALUES
('麻黄汤', '【组成】麻黄9g、桂枝6g、杏仁6g、炙甘草3g\n【功用】发汗解表，宣肺平喘。\n【主治】外感风寒表实证。恶寒发热，头身疼痛，无汗而喘，舌苔薄白，脉浮紧。\n【方解】麻黄发汗解表、宣肺平喘为君药；桂枝温经散寒、解肌发表为臣药，助麻黄发汗；杏仁降利肺气、止咳平喘为佐药；炙甘草调和诸药为使药。\n【用法】水煎服，服后覆取微似汗。', '辛温解表代表方，发汗解表第一方', '方剂', '方剂学', '解表剂', '发汗解表第一方', NOW()),
('桂枝汤', '【组成】桂枝9g、芍药9g、炙甘草6g、生姜9g、大枣3枚\n【功用】解肌发表，调和营卫。\n【主治】外感风寒表虚证。发热，恶风，汗出，鼻鸣干呕，舌苔薄白，脉浮缓。\n【方解】桂枝解肌发表为君药；芍药敛阴和营为臣药；生姜助桂解表，大枣助芍和营，共为佐药；炙甘草调和诸药为使药。\n【用法】水煎服，服后须臾啜热稀粥。', '群方之冠，调和营卫代表方', '方剂', '方剂学', '解表剂', '调和营卫第一方', NOW()),
('九味羌活汤', '【组成】羌活、防风、苍术各6g，细辛2g，川芎、白芷、生地、黄芩、甘草各3g\n【功用】发汗祛湿，兼清里热。\n【主治】外感风寒湿邪，内有蕴热证。恶寒发热，肌表无汗，头痛项强，肢体酸楚疼痛，口苦微渴。\n【方解】羌活祛风寒湿为君药；防风、苍术祛风除湿为臣药；细辛、川芎、白芷散风寒行气血，生地、黄芩清里热为佐药。', '分经论治代表方', '方剂', '方剂学', '解表剂', '分经论治', NOW()),
('小青龙汤', '【组成】麻黄、芍药、细辛、干姜、炙甘草、桂枝各9g，五味子6g，半夏9g\n【功用】解表散寒，温肺化饮。\n【主治】外寒内饮证。恶寒发热，无汗，喘咳，痰多而稀，或痰饮咳喘，不得平卧，或身体疼重。\n【方解】麻黄、桂枝解表散寒为君；干姜、细辛温肺化饮为臣；五味子敛肺，芍药敛阴，防温燥伤正为佐；半夏燥湿化痰，甘草调和诸药。', '外寒内饮代表方', '方剂', '方剂学', '解表剂', '解表化饮', NOW()),
('银翘散', '【组成】金银花、连翘各30g，桔梗、薄荷、牛蒡子各18g，竹叶、荆芥穗各12g，淡豆豉、甘草各15g\n【功用】辛凉透表，清热解毒。\n【主治】温病初起。发热无汗，或有汗不畅，微恶风寒，头痛口渴，咳嗽咽痛，舌尖红，苔薄白或薄黄。\n【方解】金银花、连翘清热解毒、芳香辟秽为君；薄荷、牛蒡子疏散风热为臣；荆芥穗、淡豆豉透邪外出为佐。', '辛凉解表代表方', '方剂', '方剂学', '解表剂', '辛凉平剂', NOW()),
('桑菊饮', '【组成】桑叶7.5g、菊花3g、杏仁6g、连翘5g、薄荷2.5g、桔梗6g、甘草2.5g、芦根6g\n【功用】疏风清热，宣肺止咳。\n【主治】风温初起。但咳，身热不甚，口微渴。\n【方解】桑叶、菊花疏风清热为君；杏仁、桔梗宣肺止咳为臣；薄荷助疏散风热，连翘清热解毒，芦根清热生津为佐。', '风温咳嗽首选方', '方剂', '方剂学', '解表剂', '辛凉轻剂', NOW()),
('麻杏石甘汤', '【组成】麻黄6g、杏仁9g、石膏24g、炙甘草6g\n【功用】辛凉宣泄，清肺平喘。\n【主治】表邪化热壅肺证。身热不解，咳逆气急鼻煽，口渴，有汗或无汗，舌苔薄白或黄，脉滑而数。\n【方解】麻黄宣肺平喘为君；石膏清泄肺热为臣，麻黄与石膏相配，宣肺而不助热，清肺而不留邪。', '清肺平喘代表方', '方剂', '方剂学', '解表剂', '宣肺泄热', NOW()),
('败毒散', '【组成】柴胡、前胡、川芎、枳壳、羌活、独活、茯苓、桔梗、人参、甘草各9g\n【功用】散寒祛湿，益气解表。\n【主治】气虚外感证。憎寒壮热，头项强痛，肢体酸痛，无汗，鼻塞声重，咳嗽有痰。\n【方解】羌活、独活散寒祛湿为君；柴胡、川芎散风邪行气血为臣；人参益气扶正为佐。', '益气解表代表方', '方剂', '方剂学', '解表剂', '益气解表', NOW()),
('大承气汤', '【组成】大黄12g、厚朴15g、枳实12g、芒硝9g\n【功用】峻下热结。\n【主治】阳明腑实证。大便不通，频转矢气，脘腹痞满，腹痛拒按，按之则硬，日晡潮热，神昏谵语。\n【方解】大黄泻热通便为君；芒硝软坚润燥为臣；厚朴、枳实行气散结为佐。', '峻下热结代表方', '方剂', '方剂学', '泻下剂', '寒下第一方', NOW()),
('温脾汤', '【组成】大黄15g、当归、干姜各9g、附子、人参、芒硝、甘草各6g\n【功用】攻下冷积，温补脾阳。\n【主治】阳虚寒积证。腹痛便秘，脐下绞结，绕脐不止，手足不温，苔白不渴，脉沉弦。\n【方解】附子、干姜温阳散寒为君；大黄泻下通便为臣；人参、当归益气养血为佐。', '温下代表方', '方剂', '方剂学', '泻下剂', '攻补兼施', NOW()),
('麻子仁丸', '【组成】麻子仁500g、芍药250g、枳实250g、大黄500g、厚朴250g、杏仁250g\n【功用】润肠泄热，行气通便。\n【主治】脾约证。肠胃燥热，脾津不足，大便干结，小便频数。\n【方解】麻子仁润肠通便为君；大黄泄热通便，杏仁降气润肠为臣。', '润下代表方', '方剂', '方剂学', '泻下剂', '脾约便秘', NOW()),
('小柴胡汤', '【组成】柴胡24g、黄芩9g、人参9g、半夏9g、甘草9g、生姜9g、大枣4枚\n【功用】和解少阳。\n【主治】少阳病证。往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦，咽干，目眩。\n【方解】柴胡疏解少阳为君；黄芩清泄少阳为臣；半夏、生姜和胃降逆，人参、大枣益气扶正为佐。', '和解少阳代表方', '方剂', '方剂学', '和解剂', '和解少阳', NOW()),
('逍遥散', '【组成】柴胡、当归、白芍、白术、茯苓各30g，甘草15g，薄荷少许，生姜少许\n【功用】疏肝解郁，养血健脾。\n【主治】肝郁血虚脾弱证。两胁作痛，头痛目眩，口燥咽干，神疲食少，或月经不调，乳房胀痛。\n【方解】柴胡疏肝解郁为君；当归、白芍养血柔肝为臣；白术、茯苓健脾祛湿为佐。', '调肝养血代表方', '方剂', '方剂学', '和解剂', '肝郁脾虚', NOW()),
('半夏泻心汤', '【组成】半夏12g、黄芩、干姜、人参各9g，黄连3g、大枣4枚、炙甘草9g\n【功用】寒热平调，消痞散结。\n【主治】寒热互结之痞证。心下痞满而不痛，呕吐，肠鸣下利。\n【方解】半夏散结消痞、降逆止呕为君；黄芩、黄连泄热为臣；干姜温中散寒，人参、大枣补中为佐。', '调和肠胃代表方', '方剂', '方剂学', '和解剂', '寒热平调', NOW()),
('四逆散', '【组成】柴胡、芍药、枳实、甘草各等分\n【功用】透邪解郁，疏肝理脾。\n【主治】阳郁厥逆证。手足不温，或腹痛，或泄利下重，脉弦。\n【方解】柴胡疏肝解郁为君；芍药柔肝养血为臣；枳实理气解郁为佐；甘草调和诸药为使。', '疏肝理脾代表方', '方剂', '方剂学', '和解剂', '透邪解郁', NOW()),
('痛泻要方', '【组成】白术90g、白芍60g、陈皮45g、防风30g\n【功用】补脾柔肝，祛湿止泻。\n【主治】脾虚肝旺之痛泻。肠鸣腹痛，大便泄泻，泻必腹痛，舌苔薄白。\n【方解】白术补脾燥湿为君；白芍柔肝缓急为臣；陈皮理气为佐；防风散肝舒脾为使。', '扶土抑木代表方', '方剂', '方剂学', '和解剂', '扶土抑木', NOW()),
('白虎汤', '【组成】石膏50g、知母18g、炙甘草6g、粳米9g\n【功用】清热生津。\n【主治】阳明气分热盛证。壮热面赤，烦渴引饮，大汗出，脉洪大有力。\n【方解】石膏清阳明胃热为君；知母清热滋阴为臣；粳米、甘草益胃护津为佐。', '清气分热代表方', '方剂', '方剂学', '清热剂', '清气分热', NOW()),
('清营汤', '【组成】犀角(水牛角代)30g、生地15g、玄参9g、竹叶心3g、麦冬9g、丹参6g、黄连5g、金银花9g、连翘6g\n【功用】清营解毒，透热养阴。\n【主治】热入营分证。身热夜甚，神烦少寐，斑疹隐隐，舌绛而干。\n【方解】水牛角清营凉血为君；生地、玄参、麦冬清热养阴为臣；金银花、连翘透热转气为佐。', '清营凉血代表方', '方剂', '方剂学', '清热剂', '清营透热', NOW()),
('黄连解毒汤', '【组成】黄连9g、黄芩6g、黄柏6g、栀子9g\n【功用】泻火解毒。\n【主治】三焦火毒证。大热烦躁，错语不眠，热病吐衄，发斑，外科痈肿疔毒。\n【方解】黄连泻心火为君；黄芩泻上焦之火，黄柏泻下焦之火为臣；栀子泻三焦之火为佐。', '苦寒直折代表方', '方剂', '方剂学', '清热剂', '泻火解毒', NOW()),
('龙胆泻肝汤', '【组成】龙胆草6g、黄芩9g、栀子9g、泽泻12g、木通9g、车前子9g、当归3g、生地9g、柴胡6g、甘草6g\n【功用】泻肝胆实火，清下焦湿热。\n【主治】肝胆实火上炎或湿热下注证。头痛目赤，胁痛口苦，耳聋耳肿，或小便淋浊，阴肿阴痒。\n【方解】龙胆草泻肝胆实火为君；黄芩、栀子苦寒泻火为臣；泽泻、木通、车前子清利湿热为佐。', '泻肝胆实火代表方', '方剂', '方剂学', '清热剂', '泻肝火', NOW()),
('仙方活命饮', '【组成】白芷、贝母、防风、赤芍、当归尾、甘草、皂角刺、穿山甲、天花粉、乳香、没药各3g，金银花、陈皮各9g\n【功用】清热解毒，消肿溃坚，活血止痛。\n【主治】疮疡肿毒初起。红肿焮痛，身热微恶寒。\n【方解】金银花清热解毒为君；当归、赤芍、乳香、没药活血散瘀为臣；穿山甲、皂角刺消肿溃坚为佐。', '疮疡之圣药', '方剂', '方剂学', '清热剂', '清热解毒', NOW()),
('左金丸', '【组成】黄连180g、吴茱萸30g\n【功用】清泻肝火，降逆止呕。\n【主治】肝火犯胃证。胁肋胀痛，嘈杂吞酸，呕吐口苦，舌红苔黄，脉弦数。\n【方解】黄连泻心火、清胃热为君；吴茱萸散肝郁、降逆气为臣佐。', '肝火犯胃代表方', '方剂', '方剂学', '清热剂', '清肝和胃', NOW()),
('苇茎汤', '【组成】苇茎60g、薏苡仁30g、瓜瓣24g、桃仁9g\n【功用】清肺化痰，逐瘀排脓。\n【主治】肺痈。咳嗽痰多，咳吐腥臭脓血，胸中隐隐作痛，舌红苔黄腻。\n【方解】苇茎清肺泄热为君；薏苡仁清热利湿为臣；瓜瓣、桃仁化痰逐瘀为佐。', '肺痈代表方', '方剂', '方剂学', '清热剂', '清肺排脓', NOW()),
('理中丸', '【组成】人参、干姜、炙甘草、白术各9g\n【功用】温中散寒，补气健脾。\n【主治】脾胃虚寒证。脘腹冷痛，呕吐下利，不欲饮食，四肢不温，舌淡苔白，脉沉细。\n【方解】干姜温中散寒为君；人参补气健脾为臣；白术健脾燥湿为佐；甘草调和诸药为使。', '温中散寒代表方', '方剂', '方剂学', '温里剂', '温中健脾', NOW()),
('小建中汤', '【组成】桂枝9g、芍药18g、炙甘草6g、生姜9g、大枣4枚、饴糖30g\n【功用】温中补虚，和里缓急。\n【主治】虚劳里急证。腹中拘急疼痛，喜温喜按，面色无华，舌淡苔白。\n【方解】饴糖温中补虚为君；芍药益阴和里为臣；桂枝温阳化气为佐。', '温中补虚缓急代表方', '方剂', '方剂学', '温里剂', '建中缓急', NOW()),
('四逆汤', '【组成】附子15g、干姜6g、炙甘草6g\n【功用】回阳救逆。\n【主治】心肾阳虚寒厥证。四肢厥逆，恶寒蜷卧，神衰欲寐，呕吐下利，舌淡苔白滑，脉微细。\n【方解】附子温肾回阳为君；干姜温中散寒为臣；甘草益气和中为佐。', '回阳救逆代表方', '方剂', '方剂学', '温里剂', '回阳救逆', NOW()),
('当归四逆汤', '【组成】当归9g、桂枝9g、芍药9g、细辛3g、炙甘草6g、通草6g、大枣8枚\n【功用】温经散寒，养血通脉。\n【主治】血虚寒厥证。手足厥寒，舌淡苔白，脉细欲绝。\n【方解】当归养血和血为君；桂枝温经通脉为臣；芍药益阴和营，细辛散寒为佐。', '养血通脉代表方', '方剂', '方剂学', '温里剂', '温经通脉', NOW()),
('阳和汤', '【组成】熟地30g、肉桂3g、麻黄2g、鹿角胶9g、白芥子6g、姜炭2g、生甘草3g\n【功用】温阳补血，散寒通滞。\n【主治】阴疽证。患处漫肿无头，皮色不变，酸痛无热，口中不渴，舌淡苔白。\n【方解】熟地、鹿角胶温阳补血为君；肉桂、姜炭温阳散寒为臣；麻黄开腠理、白芥子祛痰为佐。', '阴疽圣药', '方剂', '方剂学', '温里剂', '温阳消疽', NOW()),
('四君子汤', '【组成】人参9g、白术9g、茯苓9g、炙甘草6g\n【功用】益气健脾。\n【主治】脾胃气虚证。面色萎白，语声低微，气短乏力，食少便溏，舌淡苔白，脉虚缓。\n【方解】人参补气健脾为君；白术健脾燥湿为臣；茯苓渗湿健脾为佐；甘草调和诸药为使。', '补气健脾基本方', '方剂', '方剂学', '补益剂', '补气', NOW()),
('参苓白术散', '【组成】人参、白术、茯苓、山药、莲子、薏苡仁、扁豆、砂仁、桔梗、甘草\n【功用】益气健脾，渗湿止泻。\n【主治】脾虚湿盛证。饮食不化，胸脘痞闷，肠鸣泄泻，四肢乏力，面色萎黄。\n【方解】人参、白术、茯苓益气健脾为君；山药、莲子助健脾为臣；薏苡仁、扁豆渗湿为佐。', '培土生金代表方', '方剂', '方剂学', '补益剂', '健脾渗湿', NOW()),
('补中益气汤', '【组成】黄芪18g、人参6g、白术9g、炙甘草9g、当归3g、陈皮6g、升麻6g、柴胡6g\n【功用】补中益气，升阳举陷。\n【主治】脾胃气虚证及气虚下陷证。少气懒言，体倦肢软，面色萎白，饮食减少，或脱肛、子宫脱垂。\n【方解】黄芪补中益气、升阳举陷为君；人参、白术、甘草益气健脾为臣；升麻、柴胡升阳举陷为佐。', '益气升阳代表方', '方剂', '方剂学', '补益剂', '升阳举陷', NOW()),
('生脉散', '【组成】人参9g、麦冬9g、五味子6g\n【功用】益气生津，敛阴止汗。\n【主治】气阴两虚证。体倦气短，咽干口渴，自汗，舌干红少苔，脉虚数。\n【方解】人参大补元气为君；麦冬养阴清热为臣；五味子敛阴止汗为佐。', '气阴双补代表方', '方剂', '方剂学', '补益剂', '益气养阴', NOW()),
('四物汤', '【组成】熟地12g、当归9g、白芍9g、川芎6g\n【功用】补血调血。\n【主治】营血虚滞证。头晕目眩，心悸失眠，面色无华，妇人月经不调，量少或经闭。\n【方解】熟地滋阴养血为君；当归补血活血为臣；白芍敛阴和营，川芎活血行气为佐。', '补血调经基本方', '方剂', '方剂学', '补益剂', '补血', NOW()),
('归脾汤', '【组成】白术、茯神、黄芪、龙眼肉、酸枣仁各9g，人参、木香各6g，甘草3g，当归3g，远志3g\n【功用】益气补血，健脾养心。\n【主治】心脾气血两虚证。心悸怔忡，健忘失眠，盗汗虚热，食少体倦，面色萎黄。\n【方解】黄芪、人参补气健脾为君；当归、龙眼肉补血养心为臣；酸枣仁、远志宁心安神为佐。', '心脾两补代表方', '方剂', '方剂学', '补益剂', '补益心脾', NOW()),
('当归补血汤', '【组成】黄芪30g、当归6g\n【功用】补气生血。\n【主治】血虚发热证。肌热面赤，烦渴欲饮，脉洪大而虚，重按无力。\n【方解】黄芪大补脾肺之气，以资生血之源为君；当归养血和营为臣。', '补气生血代表方', '方剂', '方剂学', '补益剂', '补气生血', NOW()),
('八珍汤', '【组成】人参、白术、茯苓、当归、川芎、白芍、熟地各9g，甘草6g\n【功用】益气补血。\n【主治】气血两虚证。面色苍白或萎黄，头晕目眩，四肢倦怠，气短懒言，心悸怔忡。\n【方解】四君子汤补气，四物汤补血，气血双补。', '气血双补代表方', '方剂', '方剂学', '补益剂', '气血双补', NOW()),
('六味地黄丸', '【组成】熟地24g、山萸肉12g、山药12g、泽泻9g、牡丹皮9g、茯苓9g\n【功用】滋阴补肾。\n【主治】肾阴虚证。头晕耳鸣，腰膝酸软，骨蒸潮热，盗汗遗精，消渴，手足心热，舌红少苔。\n【方解】熟地滋阴补肾为君；山萸肉、山药补肝脾为臣；三泻（泽泻、丹皮、茯苓）泻浊为佐。', '滋阴补肾代表方', '方剂', '方剂学', '补益剂', '滋补肝肾', NOW()),
('肾气丸', '【组成】干地黄24g、山药12g、山茱萸12g、泽泻9g、茯苓9g、牡丹皮9g、桂枝3g、附子3g\n【功用】补肾助阳。\n【主治】肾阳不足证。腰痛脚软，身半以下常有冷感，小便不利或小便反多，舌淡而胖。\n【方解】附子、桂枝温补肾阳为君；地黄、山茱萸滋阴为臣。', '补肾阳代表方', '方剂', '方剂学', '补益剂', '温补肾阳', NOW()),
('左归丸', '【组成】熟地、山药、枸杞、山茱萸、菟丝子、鹿角胶、龟板胶、川牛膝\n【功用】滋阴补肾，填精益髓。\n【主治】肾阴不足证。头目眩晕，腰酸腿软，遗精滑泄，自汗盗汗，口燥咽干。\n【方解】熟地滋肾填精为君；山茱萸、枸杞滋阴为臣。', '纯补无泻之滋阴方', '方剂', '方剂学', '补益剂', '填精补髓', NOW()),
('右归丸', '【组成】熟地、山药、山茱萸、枸杞、菟丝子、杜仲、当归、肉桂、附子、鹿角胶\n【功用】温补肾阳，填精补血。\n【主治】肾阳不足证。气怯神疲，腹痛腰酸，肢冷，阳痿遗精。\n【方解】附子、肉桂温补肾阳为君；鹿角胶补肾填精为臣。', '温补肾阳填精方', '方剂', '方剂学', '补益剂', '温阳填精', NOW()),
('一贯煎', '【组成】北沙参、麦冬、当归各9g，生地18g，枸杞12g，川楝子4.5g\n【功用】滋阴疏肝。\n【主治】肝肾阴虚，肝气不舒证。胸脘胁痛，吞酸吐苦，咽干口燥，舌红少津。\n【方解】生地滋阴养血为君；枸杞滋肾为臣；沙参、麦冬养阴为佐；川楝子疏肝泄热。', '滋阴疏肝代表方', '方剂', '方剂学', '补益剂', '滋阴疏肝', NOW()),
('百合固金汤', '【组成】百合12g、熟地、生地、当归各9g，白芍、甘草各3g，桔梗、玄参各6g，贝母、麦冬各9g\n【功用】滋阴润肺，化痰止咳。\n【主治】肺肾阴虚，虚火上炎证。咳嗽气喘，痰中带血，咽喉燥痛，手足心热。\n【方解】百合滋阴清热为君；生地、熟地滋阴补肾为臣；麦冬、玄参养阴清热为佐。', '滋阴润肺代表方', '方剂', '方剂学', '补益剂', '滋阴润肺', NOW()),
('炙甘草汤', '【组成】炙甘草12g、生姜9g、桂枝9g、人参6g、生地30g、阿胶6g、麦冬12g、麻仁12g、大枣10枚\n【功用】益气滋阴，通阳复脉。\n【主治】气虚血弱证。脉结代，心动悸，虚赢少气，舌光少苔。\n【方解】炙甘草益气养心为君；人参、大枣补气为臣；生地、阿胶、麦冬滋阴养血为佐。', '复脉定悸代表方', '方剂', '方剂学', '补益剂', '益气复脉', NOW()),
('天王补心丹', '【组成】人参、茯苓、玄参、丹参、桔梗、远志各15g，当归、五味子、麦冬、天冬、柏子仁、酸枣仁各30g，生地120g\n【功用】滋阴养血，补心安神。\n【主治】阴虚血少，神志不安证。心悸怔忡，虚烦失眠，神疲健忘，手足心热，舌红少苔。\n【方解】生地滋阴养血为君；天冬、麦冬滋阴清热为臣；酸枣仁、柏子仁养心安神为佐。', '滋阴安神代表方', '方剂', '方剂学', '安神剂', '滋阴安神', NOW()),
('酸枣仁汤', '【组成】酸枣仁15g、甘草3g、知母6g、茯苓6g、川芎6g\n【功用】养血安神，清热除烦。\n【主治】虚烦不眠证。虚烦不得眠，心悸盗汗，头目眩晕，咽干口燥，舌红。\n【方解】酸枣仁养肝安神为君；茯苓宁心安神为臣；知母清热除烦，川芎调畅气血为佐。', '养血安神代表方', '方剂', '方剂学', '安神剂', '养肝安神', NOW()),
('安宫牛黄丸', '【组成】牛黄、郁金、犀角(水牛角代)、黄连、朱砂、栀子、雄黄、黄芩、珍珠、冰片、麝香\n【功用】清热解毒，豁痰开窍。\n【主治】邪热内陷心包证。高热烦躁，神昏谵语，中风昏迷，惊厥。\n【方解】牛黄清心解毒、豁痰开窍为君；麝香、冰片芳香开窍为臣。', '凉开三宝之首', '方剂', '方剂学', '开窍剂', '清热开窍', NOW()),
('牡蛎散', '【组成】黄芪、麻黄根、牡蛎各30g，浮小麦30g\n【功用】敛阴止汗，益气固表。\n【主治】体虚自汗、盗汗证。常自汗出，夜卧更甚，心悸惊惕，短气烦倦。\n【方解】牡蛎敛阴止汗为君；黄芪益气固表为臣；麻黄根止汗为佐。', '固表止汗代表方', '方剂', '方剂学', '固涩剂', '敛阴止汗', NOW()),
('真人养脏汤', '【组成】人参、当归、白术各6g，肉豆蔻、肉桂、炙甘草各3g，白芍15g，木香4.5g，诃子12g，罂粟壳20g\n【功用】涩肠固脱，温补脾肾。\n【主治】久泻久痢，脾肾虚寒证。大便滑脱不禁，腹痛喜温喜按，食少神疲。\n【方解】罂粟壳涩肠止泻为君；肉豆蔻、诃子温涩为臣。', '涩肠止泻代表方', '方剂', '方剂学', '固涩剂', '涩肠固脱', NOW()),
('四神丸', '【组成】肉豆蔻60g、补骨脂120g、五味子60g、吴茱萸30g\n【功用】温肾暖脾，固肠止泻。\n【主治】脾肾阳虚之五更泄。五更泄泻，不思饮食，食不消化，或久泻不愈，腹痛腰酸。\n【方解】补骨脂温补肾阳为君；肉豆蔻温脾涩肠为臣；五味子涩肠止泻为佐。', '五更泄泻代表方', '方剂', '方剂学', '固涩剂', '温肾固肠', NOW()),
('金锁固精丸', '【组成】沙苑蒺藜、芡实、莲须各60g，龙骨、牡蛎各30g\n【功用】补肾涩精。\n【主治】肾虚精关不固证。遗精滑泄，腰痛耳鸣，四肢酸软，神疲乏力。\n【方解】沙苑蒺藜补肾固精为君；芡实益肾涩精为臣；龙骨、牡蛎收敛固涩为佐。', '固精止遗代表方', '方剂', '方剂学', '固涩剂', '补肾固精', NOW()),
('完带汤', '【组成】白术、山药各30g，人参6g，白芍15g，车前子9g，苍术9g，甘草3g，陈皮2g，黑芥穗2g，柴胡2g\n【功用】补脾疏肝，化湿止带。\n【主治】脾虚肝郁，湿浊带下证。带下色白或淡黄，清稀无臭，面色苍白，倦怠便溏。\n【方解】白术、山药补脾祛湿为君；人参、苍术益气燥湿为臣。', '健脾止带代表方', '方剂', '方剂学', '固涩剂', '健脾止带', NOW()),
('越鞠丸', '【组成】香附、川芎、苍术、神曲、栀子各等分\n【功用】行气解郁。\n【主治】六郁证。胸膈痞闷，脘腹胀痛，嗳腐吞酸，恶心呕吐，饮食不消。\n【方解】香附行气解郁为君，治气郁；川芎活血治血郁；苍术燥湿治湿郁；栀子清热治火郁；神曲消食治食郁。', '通治六郁代表方', '方剂', '方剂学', '理气剂', '行气解郁', NOW()),
('半夏厚朴汤', '【组成】半夏12g、厚朴9g、茯苓12g、生姜15g、苏叶6g\n【功用】行气散结，降逆化痰。\n【主治】梅核气。咽中如有物阻，咯吐不出，吞咽不下，胸胁满闷。\n【方解】半夏化痰散结、降逆为君；厚朴行气开郁为臣；茯苓渗湿为佐。', '梅核气代表方', '方剂', '方剂学', '理气剂', '行气散结', NOW()),
('瓜蒌薤白白酒汤', '【组成】瓜蒌实12g、薤白12g、白酒适量\n【功用】通阳散结，行气祛痰。\n【主治】胸痹。胸中闷痛，甚至胸痛彻背，喘息咳唾，短气，舌苔白腻。\n【方解】瓜蒌涤痰宽胸为君；薤白通阳散结为臣。', '胸痹基础方', '方剂', '方剂学', '理气剂', '通阳宽胸', NOW()),
('苏子降气汤', '【组成】苏子9g、半夏9g、当归6g、甘草6g、前胡6g、厚朴6g、肉桂3g\n【功用】降气平喘，祛痰止咳。\n【主治】上实下虚之喘咳。咳嗽喘逆，痰多胸闷，呼多吸少，腰酸腿软。\n【方解】苏子降气祛痰为君；半夏、厚朴祛痰降逆为臣；肉桂温肾纳气为佐。', '降气平喘代表方', '方剂', '方剂学', '理气剂', '降气化痰', NOW()),
('旋覆代赭汤', '【组成】旋覆花9g、人参6g、生姜15g、代赭石9g、甘草9g、半夏9g、大枣4枚\n【功用】降逆化痰，益气和胃。\n【主治】胃虚痰阻气逆证。心下痞硬，噫气不除，或反胃呕逆。\n【方解】旋覆花下气消痰为君；代赭石重镇降逆为臣；半夏、生姜散结降逆为佐。', '降逆止呕代表方', '方剂', '方剂学', '理气剂', '和胃降逆', NOW()),
('血府逐瘀汤', '【组成】桃仁12g、红花9g、当归9g、生地9g、川芎5g、赤芍6g、牛膝9g、桔梗5g、柴胡3g、枳壳6g、甘草3g\n【功用】活血化瘀，行气止痛。\n【主治】胸中血瘀证。胸痛，头痛日久，痛如针刺而有定处，或呃逆日久不止，内热烦闷。\n【方解】桃仁、红花活血祛瘀为君；川芎、赤芍助活血为臣；柴胡、枳壳行气为佐。', '活血化瘀代表方', '方剂', '方剂学', '理血剂', '活血化瘀', NOW()),
('补阳还五汤', '【组成】黄芪120g、当归尾6g、赤芍5g、地龙3g、川芎3g、红花3g、桃仁3g\n【功用】补气活血通络。\n【主治】中风之气虚血瘀证。半身不遂，口眼歪斜，语言謇涩，口角流涎，下肢痿废。\n【方解】黄芪大补元气为君；当归尾活血为臣；赤芍、川芎、桃仁、红花活血化瘀为佐。', '益气活血通络代表方', '方剂', '方剂学', '理血剂', '补气活血', NOW()),
('生化汤', '【组成】全当归24g、川芎9g、桃仁6g、干姜2g、炙甘草2g\n【功用】养血祛瘀，温经止痛。\n【主治】产后瘀滞腹痛。恶露不行，小腹冷痛。\n【方解】当归养血活血为君；川芎活血行气为臣；桃仁活血祛瘀为佐。', '产后化瘀代表方', '方剂', '方剂学', '理血剂', '化瘀生新', NOW()),
('温经汤', '【组成】吴茱萸、麦冬各9g，当归、芍药、川芎、人参、桂枝、阿胶、牡丹皮、生姜、甘草、半夏各6g\n【功用】温经散寒，养血祛瘀。\n【主治】冲任虚寒，瘀血阻滞证。漏下不止，月经不调，或前或后，或一月再行，或经停不至，傍晚发热，手心烦热。\n【方解】吴茱萸、桂枝温经散寒为君；当归、川芎活血为臣。', '调经祖方', '方剂', '方剂学', '理血剂', '温经调经', NOW()),
('咳血方', '【组成】青黛6g、瓜蒌仁9g、海粉9g、栀子9g、诃子6g\n【功用】清肝宁肺，凉血止血。\n【主治】肝火犯肺之咳血证。咳嗽痰稠带血，咯吐不爽，心烦易怒，胸胁作痛。\n【方解】青黛、栀子清肝泻火为君；瓜蒌仁清热化痰为臣。', '肝火犯肺咳血代表方', '方剂', '方剂学', '理血剂', '清肝止血', NOW()),
('槐花散', '【组成】槐花12g、柏叶12g、荆芥穗6g、枳壳6g\n【功用】清肠止血，疏风行气。\n【主治】肠风脏毒下血。便前出血，或便后出血，或粪中带血，血色鲜红或晦暗。\n【方解】槐花清肠止血为君；侧柏叶助止血为臣。', '肠风下血代表方', '方剂', '方剂学', '理血剂', '清肠止血', NOW()),
('黄土汤', '【组成】灶心黄土30g、白术、附子、甘草、干地黄、阿胶、黄芩各9g\n【功用】温阳健脾，养血止血。\n【主治】脾阳不足，脾不统血证。大便下血，先便后血，或吐血、衄血，面色萎黄，四肢不温。\n【方解】灶心黄土温中止血为君；白术、附子温阳健脾为臣。', '温脾摄血代表方', '方剂', '方剂学', '理血剂', '温阳止血', NOW()),
('川芎茶调散', '【组成】川芎、荆芥各12g，白芷、羌活、甘草各6g，细辛3g，防风4.5g，薄荷24g\n【功用】疏风止痛。\n【主治】外感风邪头痛。偏正头痛，巅顶作痛，恶寒发热，目眩鼻塞。\n【方解】川芎活血行气、祛风止痛为君；薄荷、荆芥疏风为臣。', '治头痛基本方', '方剂', '方剂学', '治风剂', '疏散外风', NOW()),
('镇肝熄风汤', '【组成】怀牛膝30g、代赭石30g、龙骨15g、牡蛎15g、龟板15g、玄参15g、天冬15g、茵陈6g、川楝子6g、麦芽6g、甘草4.5g\n【功用】镇肝熄风，滋阴潜阳。\n【主治】类中风。头目眩晕，目胀耳鸣，脑部热痛，心中烦热，面色如醉，或肢体不利。\n【方解】怀牛膝引血下行为君；代赭石镇肝降逆为臣。', '镇肝熄风代表方', '方剂', '方剂学', '治风剂', '镇肝潜阳', NOW()),
('天麻钩藤饮', '【组成】天麻9g、钩藤12g、石决明18g、栀子9g、黄芩9g、牛膝12g、杜仲、益母草、桑寄生、夜交藤、朱茯神各9g\n【功用】平肝熄风，清热活血，补益肝肾。\n【主治】肝阳偏亢，肝风上扰证。头痛，眩晕，失眠多梦，舌红苔黄。\n【方解】天麻、钩藤平肝熄风为君；石决明平肝潜阳为臣。', '平肝熄风代表方', '方剂', '方剂学', '治风剂', '平肝潜阳', NOW()),
('大定风珠', '【组成】生白芍18g、阿胶9g、生龟板12g、干地黄18g、麻仁6g、五味子6g、生牡蛎12g、麦冬18g、炙甘草12g、鸡子黄2枚、鳖甲12g\n【功用】滋阴熄风。\n【主治】阴虚动风证。温病后期，神倦瘈疭，脉气虚弱，舌绛苔少。\n【方解】鸡子黄、阿胶滋阴养血为君；白芍、地黄、麦冬滋阴柔肝为臣。', '滋阴熄风代表方', '方剂', '方剂学', '治风剂', '滋阴熄风', NOW()),
('平胃散', '【组成】苍术15g、厚朴9g、陈皮9g、甘草4g\n【功用】燥湿运脾，行气和胃。\n【主治】湿滞脾胃证。脘腹胀满，不思饮食，口淡无味，恶心呕吐，嗳气吞酸，肢体沉重。\n【方解】苍术燥湿健脾为君；厚朴行气化湿为臣；陈皮理气和胃为佐。', '燥湿和胃代表方', '方剂', '方剂学', '祛湿剂', '燥湿和胃', NOW()),
('藿香正气散', '【组成】藿香、苏叶、白芷、大腹皮、茯苓各9g，白术、半夏曲、陈皮、厚朴、桔梗各6g，甘草3g\n【功用】解表化湿，理气和中。\n【主治】外感风寒，内伤湿滞证。恶寒发热，头痛，胸膈满闷，脘腹疼痛，恶心呕吐，肠鸣泄泻。\n【方解】藿香化湿和胃为君；苏叶、白芷解表为臣。', '化湿和中代表方', '方剂', '方剂学', '祛湿剂', '芳香化湿', NOW()),
('茵陈蒿汤', '【组成】茵陈18g、栀子9g、大黄6g\n【功用】清热利湿退黄。\n【主治】湿热黄疸。一身面目俱黄，黄色鲜明，腹微满，小便不利。\n【方解】茵陈清热利湿退黄为君；栀子清泄三焦为臣；大黄泄热通便为佐。', '湿热黄疸代表方', '方剂', '方剂学', '祛湿剂', '清热退黄', NOW()),
('三仁汤', '【组成】杏仁15g、薏苡仁18g、白蔻仁6g、厚朴6g、半夏15g、通草6g、竹叶6g、滑石18g\n【功用】宣畅气机，清利湿热。\n【主治】湿温初起及暑温夹湿。头痛恶寒，身重疼痛，面色淡黄，胸闷不饥，午后身热。\n【方解】杏仁宣上焦，白蔻仁畅中焦，薏苡仁渗下焦，三仁同用。', '湿温初起代表方', '方剂', '方剂学', '祛湿剂', '宣畅三焦', NOW()),
('五苓散', '【组成】猪苓9g、泽泻15g、白术9g、茯苓9g、桂枝6g\n【功用】利水渗湿，温阳化气。\n【主治】蓄水证。小便不利，头痛微热，烦渴欲饮，水入即吐，舌苔白，脉浮。\n【方解】泽泻利水渗湿为君；茯苓、猪苓助利水为臣；白术健脾，桂枝化气为佐。', '化气利水代表方', '方剂', '方剂学', '祛湿剂', '利水渗湿', NOW()),
('真武汤', '【组成】茯苓9g、芍药9g、白术6g、生姜9g、附子15g\n【功用】温阳利水。\n【主治】阳虚水泛证。畏寒肢冷，小便不利，四肢沉重，下肢水肿，或腹痛下利。\n【方解】附子温肾助阳为君；茯苓、白术健脾利水为臣；生姜温散水气为佐。', '温阳利水代表方', '方剂', '方剂学', '祛湿剂', '温阳化水', NOW()),
('二陈汤', '【组成】半夏15g、橘红15g、白茯苓9g、炙甘草5g\n【功用】燥湿化痰，理气和中。\n【主治】湿痰证。咳嗽痰多，色白易咯，胸膈满闷，恶心呕吐，肢体倦怠。\n【方解】半夏燥湿化痰为君；橘红理气化痰为臣；茯苓健脾渗湿为佐。', '治痰通用方', '方剂', '方剂学', '祛痰剂', '燥湿化痰', NOW()),
('温胆汤', '【组成】半夏、竹茹、枳实各6g，陈皮9g，茯苓5g，甘草3g\n【功用】理气化痰，清胆和胃。\n【主治】胆胃不和，痰热内扰证。虚烦不眠，或呕吐呃逆，惊悸不宁，癫痫。\n【方解】半夏燥湿化痰为君；竹茹清热化痰为臣；枳实、陈皮理气为佐。', '理气化痰清胆代表方', '方剂', '方剂学', '祛痰剂', '清胆和胃', NOW()),
('半夏白术天麻汤', '【组成】半夏9g、天麻6g、茯苓6g、橘红6g、白术15g、甘草3g\n【功用】化痰熄风，健脾祛湿。\n【主治】风痰上扰证。眩晕头痛，胸膈痞闷，恶心呕吐，舌苔白腻，脉弦滑。\n【方解】半夏燥湿化痰为君；天麻平肝熄风为臣；白术健脾为佐。', '风痰眩晕代表方', '方剂', '方剂学', '祛痰剂', '化痰熄风', NOW()),
('保和丸', '【组成】山楂18g、神曲6g、半夏、茯苓各9g，陈皮、连翘、莱菔子各3g\n【功用】消食和胃。\n【主治】食滞胃脘证。脘腹痞满胀痛，嗳腐吞酸，恶食呕逆，舌苔厚腻。\n【方解】山楂消食化积为君；神曲消食健胃为臣；半夏、陈皮理气化湿为佐。', '消食导滞代表方', '方剂', '方剂学', '消食剂', '消食和胃', NOW()),
('健脾丸', '【组成】人参、白术、陈皮、麦芽各60g，山楂45g，枳实90g\n【功用】健脾和胃，消食止泻。\n【主治】脾胃虚弱，食积内停证。食少难消，脘腹痞满，大便溏薄，苔腻微黄。\n【方解】人参、白术健脾为君；山楂、神曲消食为臣。', '健脾消食代表方', '方剂', '方剂学', '消食剂', '健脾消食', NOW()),
('清暑益气汤', '【组成】西洋参5g、石斛15g、麦冬9g、黄连3g、竹叶6g、荷梗15g、知母6g、甘草3g、粳米15g、西瓜翠衣30g\n【功用】清暑益气，养阴生津。\n【主治】暑热气津两伤证。身热汗多，口渴心烦，小便短赤，体倦少气，精神不振。\n【方解】西瓜翠衣清热解暑为君；西洋参益气生津为臣。', '暑伤气阴代表方', '方剂', '方剂学', '祛暑剂', '清暑益气', NOW()),
('玉女煎', '【组成】石膏15g、熟地15g、麦冬6g、知母5g、牛膝5g\n【功用】清胃热，滋肾阴。\n【主治】胃热阴虚证。头痛，牙痛，齿松牙衄，烦热干渴，舌红苔黄而干。\n【方解】石膏清胃热为君；熟地滋肾阴为臣；麦冬、知母滋阴清热为佐。', '清胃滋阴代表方', '方剂', '方剂学', '清热剂', '清胃滋阴', NOW()),
('芍药汤', '【组成】芍药30g、当归15g、黄连15g、槟榔6g、木香6g、甘草6g、大黄9g、黄芩15g、肉桂5g\n【功用】清热燥湿，调气和血。\n【主治】湿热痢疾。腹痛，便脓血，赤白相兼，里急后重，肛门灼热。\n【方解】芍药调和气血为君；黄连、黄芩清热燥湿为臣。', '湿热痢疾代表方', '方剂', '方剂学', '清热剂', '清热治痢', NOW());
